'use client';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { Badge } from '@/registry/ndeko/ui/badge';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { WORKSPACE_NAME, type License, type LicenseId } from './data';
import { LicenseCard } from './license-card';
import {
  COPIED_MS,
  INITIAL,
  keyTextOf,
  licenseOf,
  LOOP_AFTER_MS,
  reducer,
  REGENERATE_MS,
  RESTING,
  RETURN_GAPS_MS,
  returnsOf,
  SCRIPT,
} from './session';
import { SettingsFrame, SettingsSection } from './settings-frame';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

export default function Settings06() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule, clearAll } = useTimeouts();
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function reveal(id: LicenseId) {
    act({ type: 'revealToggled', id });
  }

  async function copy(license: License) {
    try {
      await navigator.clipboard.writeText(keyTextOf(license.groups));
    } catch {
      act({ type: 'copyFailed' });
      return;
    }
    act({ type: 'copied', id: license.id });
    schedule(() => act({ type: 'copyFaded' }), COPIED_MS);
  }

  function toggleRegenerate(id: LicenseId) {
    const after = reducer(state, { type: 'regenerateToggled', id });
    act({ type: 'regenerateToggled', id });
    if (after.confirmingId === id) {
      focusLater(`[data-keep-key="${id}"]`);
    }
  }

  function keep() {
    const id = state.confirmingId;
    act({ type: 'regenerateCancelled' });
    if (id) {
      focusLater(`[data-regenerate="${id}"]`);
    }
  }

  /** The machines that held the old key come back one after another with the new one. */
  function bringMachinesBack(id: LicenseId, used: number, round: number) {
    const returns = returnsOf(used);
    let wait = 0;
    returns.forEach((count, index) => {
      wait += RETURN_GAPS_MS[index];
      schedule(() => act({ type: 'activated', id, used: count, round }), wait);
    });
  }

  function confirm(id: LicenseId) {
    const license = licenseOf(state, id);
    if (!license) {
      return;
    }
    const round = state.made[id] + 1;
    act({ type: 'regenerateConfirmed', id });
    focusLater(`[data-regenerate="${id}"]`);
    schedule(() => {
      act({ type: 'regenerated', id });
      bringMachinesBack(id, license.used, round);
    }, REGENERATE_MS);
  }

  /** A key on its way belongs to the round it was asked for in. */
  function replay() {
    clearAll();
    restart();
  }

  return (
    <ClockGate isActive={isInView}>
      <SettingsFrame
        ref={ref}
        title='License keys'
        line={`The keys that unlock the Tidewell apps ${WORKSPACE_NAME} pays for. Show one again whenever you need it.`}
        aside={
          <ReplayButton isShown={canReplay} onReplay={replay} label='Replay' />
        }
      >
        <SettingsSection
          title='Your licenses'
          line={
            <span className='flex flex-wrap items-center gap-x-1.5 gap-y-1'>
              Sample keys with DEMO in them: they unlock nothing
              <Badge variant='secondary'>Illustrative</Badge>
            </span>
          }
        >
          <div className='grid items-start gap-4 @3xl:grid-cols-2'>
            {state.licenses.map((license) => (
              <LicenseCard
                key={license.id}
                license={license}
                state={state}
                pressed={pressed}
                onReveal={reveal}
                onCopy={copy}
                onRegenerate={toggleRegenerate}
                onKeep={keep}
                onConfirm={confirm}
              />
            ))}
          </div>
        </SettingsSection>
        <LiveRegion message={message} />
      </SettingsFrame>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';
import { Fragment, useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import {
  CheckIcon,
  CopyIcon,
  EyeIcon,
  EyeOffIcon,
} from '@/registry/ndeko/lib/icons';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';

import {
  NEAR_LIMIT_SHARE,
  type License,
  type LicenseId,
  type LicenseStatus,
} from './data';
import { keyTextOf, type LicenseState } from './session';
import { SURFACE } from './settings-frame';

const MASK = '••••';

const ROLL_STAGGER_S = 0.06;

const ROLL_IN = { y: '0%', opacity: 1, filter: 'blur(0px)' };

const ROLL_BELOW = { y: '100%', opacity: 0, filter: 'blur(4px)' };

const ROLL_ABOVE = { y: '-100%', opacity: 0, filter: 'blur(4px)' };

const FADE_IN = { opacity: 1 };

const FADE_OUT = { opacity: 0 };

const STATUS_VARIANT: Record<LicenseStatus, 'success' | 'warning'> = {
  active: 'success',
  expiring: 'warning',
};

const REGENERATE_LABELS: Record<MorphState, string> = {
  idle: 'Regenerate key',
  busy: 'Regenerating',
  done: 'Regenerated',
};

type Tone = 'calm' | 'near';

const FILL_TONE: Record<Tone, string> = {
  calm: 'bg-primary',
  near: 'bg-warning',
};

const NOTE_TONE: Record<Tone, string> = {
  calm: 'text-muted-foreground',
  near: 'text-warning-foreground',
};

function rollOf(shouldReduceMotion: boolean, index: number) {
  const transition: Transition = {
    duration: 0.28,
    ease: EASE_OUT_STRONG,
    delay: index * ROLL_STAGGER_S,
  };
  if (shouldReduceMotion) {
    return { initial: FADE_OUT, animate: FADE_IN, exit: FADE_OUT, transition };
  }
  return {
    initial: ROLL_BELOW,
    animate: ROLL_IN,
    exit: ROLL_ABOVE,
    transition,
  };
}

/** The first and the last groups stay readable, so a hidden key can still be told apart. */
function shownGroupOf(
  group: string,
  index: number,
  count: number,
  isRevealed: boolean
) {
  const isEnd = index === 0 || index === count - 1;
  if (isRevealed || isEnd) {
    return group;
  }
  return MASK;
}

function GroupSlot({ text, index }: { text: string; index: number }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const roll = rollOf(shouldReduceMotion, index);

  return (
    <span className='relative inline-flex overflow-hidden'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span key={text} className='inline-block' {...roll}>
          {text}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

function spokenKeyOf(groups: string[], isRevealed: boolean) {
  if (isRevealed) {
    return `Key ${keyTextOf(groups)}`;
  }
  const last = groups[groups.length - 1];
  return `Key hidden, ends with ${last}`;
}

/** Each group rolls on its own, a beat after the one before: shown, hidden or made anew. */
function KeyText({
  groups,
  isRevealed,
}: {
  groups: string[];
  isRevealed: boolean;
}) {
  const shown = groups.map((group, index) =>
    shownGroupOf(group, index, groups.length, isRevealed)
  );

  return (
    <span className='flex min-w-0 flex-wrap items-center font-mono text-[13px]'>
      <span className='sr-only'>{spokenKeyOf(groups, isRevealed)}</span>
      <span aria-hidden='true' className='flex flex-wrap items-center'>
        {shown.map((group, index) => (
          <Fragment key={`group-${index}`}>
            {index > 0 && (
              <span className='text-muted-foreground px-0.5'>-</span>
            )}
            <GroupSlot text={group} index={index} />
          </Fragment>
        ))}
      </span>
    </span>
  );
}

function toneOf(used: number, limit: number): Tone {
  const share = used / limit;
  if (share >= NEAR_LIMIT_SHARE) {
    return 'near';
  }
  return 'calm';
}

function countOf(count: number, words: { one: string; many: string }) {
  if (count === 1) {
    return `1 ${words.one}`;
  }
  return `${count} ${words.many}`;
}

function meterNoteOf(license: License, isFresh: boolean) {
  const left = license.limit - license.used;
  const isFull = left <= 0;
  if (isFresh && license.used === 0) {
    return `Every ${license.holders.one} signs in again with the new key`;
  }
  if (isFull) {
    return `All ${countOf(license.limit, license.unit)} in use: one more ${license.holders.one} cannot start`;
  }
  return `${countOf(left, license.unit)} left`;
}

function SeatMeter({
  license,
  isFresh,
}: {
  license: License;
  isFresh: boolean;
}) {
  const tone = toneOf(license.used, license.limit);
  const share = license.used / license.limit;
  const fillStyle = { transform: `scaleX(${share})` };
  const note = meterNoteOf(license, isFresh);
  const label = license.meterLabel;
  const spokenValue = `${license.used} of ${license.limit} ${license.unit.many} in use`;

  return (
    <div className='flex flex-col gap-1.5'>
      <p className='flex items-baseline justify-between gap-3 text-xs'>
        <span className='text-muted-foreground'>{label}</span>
        <span className='tabular-nums'>
          <MotionNumber value={license.used} />
          <span className='text-muted-foreground'> of {license.limit}</span>
        </span>
      </p>
      <div
        role='meter'
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={license.limit}
        aria-valuenow={license.used}
        aria-valuetext={spokenValue}
        className='bg-foreground/10 h-1.5 overflow-hidden rounded-full'
      >
        <span
          style={fillStyle}
          className={cn(
            'block h-full origin-left rounded-full transition-[transform,background-color] duration-500 ease-(--ease-out-strong) rtl:origin-right',
            FILL_TONE[tone]
          )}
        />
      </div>
      <p className={cn('text-xs text-pretty', NOTE_TONE[tone])}>
        <Swap swapKey={note}>{note}</Swap>
      </p>
    </div>
  );
}

function holdersLineOf(license: License) {
  if (license.used === 0) {
    return `No ${license.holders.one} uses it yet, so none has to sign in again.`;
  }
  const holders = countOf(license.used, license.holders);
  return `The ${holders} using it ask for the new one.`;
}

type RegenerateConfirmProps = {
  license: License;
  pressed: string | null;
  onKeep: () => void;
  onConfirm: (id: LicenseId) => void;
};

function RegenerateConfirm({
  license,
  pressed,
  onKeep,
  onConfirm,
}: RegenerateConfirmProps) {
  const holdersLine = holdersLineOf(license);

  function keepOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onKeep();
  }

  return (
    <div
      role='group'
      aria-label={`Regenerate the key for ${license.product}`}
      onKeyDown={keepOnEscape}
      className='bg-destructive/[0.06] flex flex-col gap-3 rounded-lg p-3'
    >
      <p className='text-[13px] text-pretty'>
        <span className='font-medium'>The old key stops working at once.</span>{' '}
        {holdersLine}
      </p>
      <div className='flex flex-wrap justify-end gap-2'>
        <Button
          type='button'
          variant='ghost'
          size='sm'
          data-keep-key={license.id}
          onClick={onKeep}
        >
          Keep this key
        </Button>
        <Button
          type='button'
          variant='destructive'
          size='sm'
          onClick={() => onConfirm(license.id)}
          className={pressedSolidOf(pressed === `confirm-${license.id}`)}
        >
          Regenerate key
        </Button>
      </div>
    </div>
  );
}

function termLineOf(license: License, isFresh: boolean) {
  if (isFresh) {
    return 'New key made just now. The old one no longer works';
  }
  return `Issued ${license.issuedOn} · ${license.termLine}`;
}

function revealLabelOf(isRevealed: boolean, product: string) {
  if (isRevealed) {
    return `Hide the key for ${product}`;
  }
  return `Show the key for ${product}`;
}

function copyLabelOf(isCopied: boolean, product: string) {
  if (isCopied) {
    return 'Copied';
  }
  return `Copy the key for ${product}`;
}

function regenerateStateOf(isRegenerating: boolean): MorphState {
  if (isRegenerating) {
    return 'busy';
  }
  return 'idle';
}

type LicenseCardProps = {
  license: License;
  state: LicenseState;
  pressed: string | null;
  onReveal: (id: LicenseId) => void;
  onCopy: (license: License) => void;
  onRegenerate: (id: LicenseId) => void;
  onKeep: () => void;
  onConfirm: (id: LicenseId) => void;
};

export function LicenseCard({
  license,
  state,
  pressed,
  onReveal,
  onCopy,
  onRegenerate,
  onKeep,
  onConfirm,
}: LicenseCardProps) {
  const titleId = useId();
  const id = license.id;
  const isRevealed = state.revealedIds.includes(id);
  const isCopied = state.copiedId === id;
  const isConfirming = state.confirmingId === id;
  const isRegenerating = state.regeneratingId === id;
  const isFresh = state.freshIds.includes(id);
  const termLine = termLineOf(license, isFresh);

  return (
    <article
      aria-labelledby={titleId}
      className={cn(SURFACE, 'flex flex-col gap-4 p-4 @xl:p-5')}
    >
      <header className='flex items-start gap-3'>
        <CompanyMark seed={license.product} size='lg' />
        <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
          <h3 id={titleId} className='text-sm font-medium'>
            {license.product}
          </h3>
          <p className='text-muted-foreground text-xs'>{license.plan}</p>
        </div>
        <Badge variant={STATUS_VARIANT[license.status]}>
          {license.statusLabel}
        </Badge>
      </header>
      <div className='flex flex-col gap-2'>
        <div className='bg-foreground/[0.04] flex items-center gap-2 rounded-lg py-1 ps-3 pe-1'>
          <KeyText groups={license.groups} isRevealed={isRevealed} />
          <span className='ms-auto flex shrink-0 items-center'>
            <Button
              type='button'
              variant='ghost'
              size='icon-sm'
              aria-label={revealLabelOf(isRevealed, license.product)}
              onClick={() => onReveal(id)}
              className={cn(
                'text-muted-foreground',
                pressedQuietOf(pressed === `reveal-${id}`)
              )}
            >
              <Swap swapKey={String(isRevealed)}>
                {isRevealed && <EyeOffIcon />}
                {!isRevealed && <EyeIcon />}
              </Swap>
            </Button>
            <Button
              type='button'
              variant='ghost'
              size='icon-sm'
              aria-label={copyLabelOf(isCopied, license.product)}
              onClick={() => onCopy(license)}
              className={cn(
                'text-muted-foreground',
                pressedQuietOf(pressed === `copy-${id}`)
              )}
            >
              <Swap swapKey={String(isCopied)}>
                {isCopied && <CheckIcon />}
                {!isCopied && <CopyIcon />}
              </Swap>
            </Button>
          </span>
        </div>
        <p className='text-muted-foreground flex text-xs'>
          <Swap swapKey={termLine}>{termLine}</Swap>
        </p>
      </div>
      <SeatMeter license={license} isFresh={isFresh} />
      <div className='flex flex-col gap-3'>
        <div className='flex justify-end'>
          <MorphButton
            type='button'
            variant='outline'
            size='sm'
            data-regenerate={id}
            aria-expanded={isConfirming}
            state={regenerateStateOf(isRegenerating)}
            labels={REGENERATE_LABELS}
            onClick={() => onRegenerate(id)}
            className={pressedQuietOf(pressed === `regenerate-${id}`)}
          />
        </div>
        <Fold open={isConfirming}>
          <RegenerateConfirm
            license={license}
            pressed={pressed}
            onKeep={onKeep}
            onConfirm={onConfirm}
          />
        </Fold>
      </div>
    </article>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { rowPresenceOf, SPRING } from '@/registry/ndeko/lib/motion-presets';

export const SURFACE =
  'bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

const NUDGE = { initial: { x: 4 }, animate: { x: 0 } };

const STILL = { initial: false, animate: { x: 0 } };

function nudgeOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return STILL;
  }
  return NUDGE;
}

export function describedByOf(hasError: boolean, errorId: string) {
  if (hasError) {
    return errorId;
  }
  return undefined;
}

type SettingsFrameProps = {
  ref?: React.Ref<HTMLDivElement>;
  title: string;
  line: string;
  /** Sits beside the title: the Replay of the demonstration. */
  aside?: React.ReactNode;
  children: React.ReactNode;
};

/** A settings page that follows its own width: one column, the title above, the sections under it. */
export function SettingsFrame({
  ref,
  title,
  line,
  aside,
  children,
}: SettingsFrameProps) {
  return (
    <div
      ref={ref}
      className='bg-background text-foreground @container min-h-dvh w-full'
    >
      <div className='mx-auto flex w-full max-w-3xl flex-col gap-8 px-4 py-8 @2xl:px-6 @2xl:py-10'>
        <header className='flex flex-wrap items-start gap-x-3 gap-y-2'>
          <div className='flex min-w-0 flex-1 basis-64 flex-col gap-1'>
            <h1 className='text-2xl font-semibold text-balance @xl:text-3xl'>
              {title}
            </h1>
            <p className='text-muted-foreground text-[13px] text-pretty'>
              {line}
            </p>
          </div>
          {aside}
        </header>
        {children}
      </div>
    </div>
  );
}

type SettingsSectionProps = {
  title: string;
  line?: React.ReactNode;
  action?: React.ReactNode;
  children: React.ReactNode;
};

export function SettingsSection({
  title,
  line,
  action,
  children,
}: SettingsSectionProps) {
  const headingId = useId();

  return (
    <section aria-labelledby={headingId} className='flex flex-col gap-3'>
      <div className='flex flex-wrap items-end justify-between gap-x-3 gap-y-2'>
        <div className='flex min-w-0 flex-col gap-0.5'>
          <h2 id={headingId} className='text-sm font-medium'>
            {title}
          </h2>
          {line && (
            <p className='text-muted-foreground text-xs text-pretty'>{line}</p>
          )}
        </div>
        {action}
      </div>
      {children}
    </section>
  );
}

type ErrorLineProps = {
  /** The field points to it with `aria-describedby` while it shows. */
  id: string;
  error: string | null;
  /** A new refusal of the same entry nudges the line again. */
  attempts: number;
};

/** A refusal grows in under its field, nudges 4px, and folds away once the person types again. */
export function ErrorLine({ id, error, attempts }: ErrorLineProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);
  const nudge = nudgeOf(shouldReduceMotion);

  return (
    <AnimatePresence initial={false}>
      {error && (
        <motion.div key='error' className='overflow-hidden' {...presence}>
          <motion.p
            key={attempts}
            id={id}
            className='text-destructive-ink pt-0.5 text-xs text-pretty'
            transition={SPRING}
            {...nudge}
          >
            {error}
          </motion.p>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import { LICENSES, NEXT_KEYS, type License, type LicenseId } from './data';

export type LicenseState = {
  licenses: License[];
  revealedIds: LicenseId[];
  copiedId: LicenseId | null;
  /** The license whose Regenerate waits for a confirm, in place under its key. */
  confirmingId: LicenseId | null;
  regeneratingId: LicenseId | null;
  /** Licenses whose key was made since the page loaded: their line says the old key stopped. */
  freshIds: LicenseId[];
  /** Keys made per license since the page loaded. A sign-in counted for an older key is ignored. */
  made: Record<LicenseId, number>;
  spoken: string;
};

export type LicenseAction =
  | { type: 'revealToggled'; id: LicenseId }
  | { type: 'copied'; id: LicenseId }
  | { type: 'copyFaded' }
  | { type: 'copyFailed' }
  | { type: 'regenerateToggled'; id: LicenseId }
  | { type: 'regenerateCancelled' }
  | { type: 'regenerateConfirmed'; id: LicenseId }
  | { type: 'regenerated'; id: LicenseId }
  | { type: 'activated'; id: LicenseId; used: number; round: number };

type Step = SessionStep<LicenseState, LicenseAction>;

/** How long a new key takes to be issued. */
export const REGENERATE_MS = 900;

/** How long Copy shows its check. */
export const COPIED_MS = 1600;

/** The waits between the machines that come back with a new key: a third, two thirds, then all. */
export const RETURN_GAPS_MS = [1500, 1300, 1200];

export const INITIAL: LicenseState = {
  licenses: LICENSES,
  revealedIds: [],
  copiedId: null,
  confirmingId: null,
  regeneratingId: null,
  freshIds: [],
  made: { desktop: 0, server: 0 },
  spoken: '',
};

export function licenseOf(state: LicenseState, id: LicenseId) {
  return state.licenses.find((license) => license.id === id);
}

export function keyTextOf(groups: string[]) {
  return groups.join('-');
}

export function returnsOf(used: number) {
  const first = Math.ceil(used / 3);
  const second = Math.ceil((used * 2) / 3);
  return [first, second, used];
}

function withLicense(
  state: LicenseState,
  id: LicenseId,
  change: Partial<License>
): LicenseState {
  const licenses = state.licenses.map((license) => {
    if (license.id !== id) {
      return license;
    }
    return { ...license, ...change };
  });
  return { ...state, licenses };
}

function revealToggled(state: LicenseState, id: LicenseId): LicenseState {
  const license = licenseOf(state, id);
  if (!license) {
    return state;
  }
  const isRevealed = state.revealedIds.includes(id);
  if (isRevealed) {
    const revealedIds = state.revealedIds.filter((other) => other !== id);
    return {
      ...state,
      revealedIds,
      spoken: `Key for ${license.product} hidden`,
    };
  }
  const revealedIds = [...state.revealedIds, id];
  return { ...state, revealedIds, spoken: `Key for ${license.product} shown` };
}

function regenerateToggled(state: LicenseState, id: LicenseId): LicenseState {
  const isBusy = state.regeneratingId !== null;
  if (isBusy) {
    return state;
  }
  if (state.confirmingId === id) {
    return { ...state, confirmingId: null, spoken: '' };
  }
  return {
    ...state,
    confirmingId: id,
    spoken: 'The old key stops working once a new one is made. Confirm below',
  };
}

function regenerateConfirmed(state: LicenseState, id: LicenseId): LicenseState {
  if (state.confirmingId !== id) {
    return state;
  }
  return {
    ...state,
    confirmingId: null,
    regeneratingId: id,
    spoken: 'Making a new key',
  };
}

function nextGroupsOf(id: LicenseId, made: number) {
  const keys = NEXT_KEYS[id];
  const index = made % keys.length;
  return keys[index];
}

function without(ids: LicenseId[], id: LicenseId) {
  return ids.filter((other) => other !== id);
}

/** Every machine signs in again with the new key, so the places in use start from none. */
function regenerated(state: LicenseState, id: LicenseId): LicenseState {
  const license = licenseOf(state, id);
  const isMaking = state.regeneratingId === id;
  if (!license || !isMaking) {
    return state;
  }
  const groups = nextGroupsOf(id, state.made[id]);
  const next = withLicense(state, id, { groups, used: 0 });
  return {
    ...next,
    regeneratingId: null,
    revealedIds: [...without(state.revealedIds, id), id],
    freshIds: [...without(state.freshIds, id), id],
    made: { ...state.made, [id]: state.made[id] + 1 },
    spoken: `New key for ${license.product}. The old one no longer works`,
  };
}

function activated(
  state: LicenseState,
  id: LicenseId,
  used: number,
  round: number
): LicenseState {
  const license = licenseOf(state, id);
  const isCurrentKey = state.made[id] === round;
  if (!license || !isCurrentKey) {
    return state;
  }
  const capped = Math.min(used, license.limit);
  return withLicense(state, id, { used: capped });
}

export function reducer(
  state: LicenseState,
  action: LicenseAction
): LicenseState {
  switch (action.type) {
    case 'revealToggled':
      return revealToggled(state, action.id);
    case 'copied':
      return { ...state, copiedId: action.id, spoken: 'Key copied' };
    case 'copyFaded':
      return { ...state, copiedId: null };
    case 'copyFailed':
      return {
        ...state,
        spoken: 'Copy did not work. Show the key and copy it by hand',
      };
    case 'regenerateToggled':
      return regenerateToggled(state, action.id);
    case 'regenerateCancelled':
      return { ...state, confirmingId: null, spoken: 'The key stays as it is' };
    case 'regenerateConfirmed':
      return regenerateConfirmed(state, action.id);
    case 'regenerated':
      return regenerated(state, action.id);
    case 'activated':
      return activated(state, action.id, action.used, action.round);
  }
}

const DESKTOP_USED = licenseOf(INITIAL, 'desktop')?.used ?? 0;

const DESKTOP_RETURNS = returnsOf(DESKTOP_USED);

/** The key is hidden again while the last machines are still coming back. */
const HIDE_AFTER_MS = 600;

function desktopReturned(index: number): LicenseAction {
  const used = DESKTOP_RETURNS[index];
  return { type: 'activated', id: 'desktop', used, round: 1 };
}

/**
 * The key is shown and copied, then Regenerate asks first. That is where the page rests under
 * reduced motion: the key in full and the warning that the old one stops.
 */
